head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDINF99001";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldinf99001.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_movePage_onclick
 * @description btn_movePage 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_movePage_onclick = async function(e){
    try {
        await scwin.movePage(01)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf99001.btn_movePage_onclick' }); }
};

/**
 * @method
 * @name btn_movePage_2_onclick
 * @description btn_movePage_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_movePage_2_onclick = async function(e){
    try {
        await scwin.movePage(01)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf99001.btn_movePage_2_onclick' }); }
};

/**
 * @method
 * @name btn_movePage_3_onclick
 * @description btn_movePage_3 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_movePage_3_onclick = async function(e){
    try {
        await scwin.movePage(03)

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldinf99001.btn_movePage_3_onclick' }); }
};

/**
 * @method
 * @name btn_self_onclick
 * @description btn_self 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_self_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldinf99001.btn_self_onclick' }); }
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name movePage
 * @description move Page 처리
 * @param {*} div div
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.movePage = async function (div) {
    const grpCd = ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).parent).form.dnld_grp_tp_cd.value;
    if (grpCd === '01' || grpCd === '02') {
        if (div === '01') {
            ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).parent).popupDownlist01();
            $c.win.closePopup();
        } else {
            await $c.win.alert("국세청 및 한국은행은 '기타기관'으로 접속 할 수 없습니다.");
        }
    } else {
        if (grpCd === '03') {
            if (div === '03') {
                ((($c.data.getParameter() && typeof $c.data.getParameter() === 'object' && Object.keys($c.data.getParameter()).length) ? $c.data.getParameter() : scwin.openerScwin()).parent).popupDownlist03();
                $c.win.closePopup();
            } else {
                await $c.win.alert("기타기관은 '국세청 및 한국은행'으로 접속 할 수 없습니다.");
            }
        }
    }
};

/**
 * @method
 * @name opener
 * @description 부모 화면 scope(browserPopup/pageFramePopup 공통 — $c.win.getOpenerScope). 단독 진입이거나 부모가 닫혀 없으면
 * @returns {Object} 부모 화면 scope 또는 빈 scope
 * @hidden N
 */
scwin.opener = function () {
    const scope = ($c.win && $c.win.getOpenerScope) ? $c.win.getOpenerScope() : null;
    return scope || { getComponentById: function () { return null; }, scwin: {} };
};

/**
 * @method
 * @name openerScwin
 * @description 부모 화면의 scwin(함수·전역 접근용). 부모가 없으면 빈 객체
 * @returns {Object} 부모 scwin 또는 {}
 * @hidden N
 */
scwin.openerScwin = function () {
    return scwin.opener().scwin || {};
};
